import{_ as i,l as t,o as e,c as l,v as o,p as s,x as r,d as h,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"相关性崩溃","description":"","frontmatter":{"title":"相关性崩溃","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/correlation-breakdown.md","filePath":"quant/correlation-breakdown.md","lastUpdated":1789023840000}'),E={name:"quant/correlation-breakdown.md"};function p(u,a,m,B,g,C){const n=t("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="相关性崩溃" tabindex="-1">相关性崩溃 <a class="header-anchor" href="#相关性崩溃" aria-label="Permalink to &quot;相关性崩溃&quot;">​</a></h1><div class="epigraph"><p>危机里资产一起跌，并不是相关矩阵偶然坏了：杠杆、抵押与市场流动性把原本分散的持仓逼进同一条卖出的窄路。</p><footer>—— 对照 Brunnermeier, Deciphering the Liquidity and Credit Crunch 2007–2008, JEP 2009</footer></div><p><a href="/quant/regime-break-risk">上一课</a>把体制切换失效写成旧参数在断点后仍被用于交易：反复马尔可夫体制与一次性结构断裂是不同装置，实时不能使用全样本才知道的 \\(\\tau\\)。缺口是分散化依赖的那个数字：压力期共同运动远强于平静期，可能是尾部依赖升高、异方差造成的相关高估，或融资约束下的同步减仓。Longin–Solnik 与 Ang–Chen 记录下行端更黏。本课区分这三层，不重写 Bai–Perron 的断点检验。它与 <a href="/quant/dcc">DCC</a>、<a href="/quant/copula">Copula</a> 是同一现象的不同写法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记两资产收益的线性相关为 \\(\\rho\\)。风险管理用一段滚动窗口估 \\(\\hat\\rho\\)，再拿去优化或报 VaR。压力日出现后，\\(\\hat\\rho\\) 跳升，组合波动远高于 \\(\\mathbf{w}^\\top\\Sigma\\mathbf{w}\\) 在平静期的值。问题有三层。第一，线性相关不是尾部依赖：高斯 copula 可以有很高的 \\(\\rho\\) 而渐进尾独立，也可以有中等 \\(\\rho\\) 而在极值上很黏。第二，波动升高等于把共同因子放大，Forbes 与 Rigobon（2002）证明异方差会把「传染」测高——条件于高波动的相关，即使无条件相关不变也会变大。第三，即使统计相关没变，杠杆与止损让所有策略同时减仓，价格路径仍会高度同步。Loretan 与 English（2000）系统讨论过「correlation breakdown」作为压力期现象时，必须先处理波动与样本的定义。</p><p>对配置而言，失败的不是「相关的点估计」，而是<strong>用平静期 \\(\\Sigma\\) 去做的最优权重在压力期的风险贡献</strong>。风险平价、最小方差会把权重堆到「过去低相关」的资产上；一旦这些资产在危机里被同一融资链绑在一起，事后集中度最高。</p><h3 id="下行相关不是对称相关的一个分位" tabindex="-1">下行相关不是对称相关的一个分位 <a class="header-anchor" href="#下行相关不是对称相关的一个分位" aria-label="Permalink to &quot;下行相关不是对称相关的一个分位&quot;">​</a></h3><p>Longin–Solnik 用多元极值理论看超越阈值的相关：大跌端的 exceedance correlation 高于大涨端。Ang–Chen 在美股里对「双双下跌」与「双双上涨」分别估相关，并检验相对常相关的偏离。含义是：用全样本 \\(\\rho\\) 或用升市 \\(\\rho\\) 去做空头对冲，会系统性低估需要的对冲比。这不是把 DCC 的 \\(R_t\\) 在跌日读得高一点就结束——DCC 仍是线性相关的动态，不自动等于尾部 copula 的依赖参数。</p><p><span class="marginnote">「相关到 1」几乎从不是字面的 \\(\\rho=1\\)。更常见的是：残差里的第一主成分解释方差突然上升，或下行 exceedance correlation 从 0.3 走到 0.7。风控语言应说清是哪一个数字，否则无法校准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>先除波动再看相关。</strong> 与 DCC 的第一步相同：用 GARCH 或已实现波动标准化，再估相关。若标准化之后压力日仍高度同向，才是依赖结构的变化，而不是 Forbes–Rigobon 偏差。报告时应同时给：原始滚动相关、剔除波动后的相关、以及下行阈值上的 exceedance correlation。</p><p><strong>Copula 与极值。</strong> 把边缘与依赖分开：边缘用肥尾，依赖用 t copula 或 Clayton 一类下尾 copula。高斯 copula 在 2008 年 CDO 定价里的恶名，正是「中等 \\(\\rho\\) + 高斯尾独立」无法生成足够的联合违约。组合风险若只输入相关矩阵，等于把 copula 选成了高斯。</p><p><strong>经济约束情景。</strong> 在 Brunnermeier–Pedersen 的逻辑下，设融资冲击让一组可抵押资产同时被抛售，把这组资产的残差相关临时抬到接近 1，同时保持其他资产不动。这比把全市场 \\(\\rho\\) 乘 1.5 更接近机制，也能避免对真正对冲工具（例如某些趋势与期权）错误施压。</p><h3 id="估计窗口与「崩溃」的定义" tabindex="-1">估计窗口与「崩溃」的定义 <a class="header-anchor" href="#估计窗口与「崩溃」的定义" aria-label="Permalink to &quot;估计窗口与「崩溃」的定义&quot;">​</a></h3><p>短窗口：相关噪声大，容易把两周同向当成结构。长窗口：把 2008 稀释进十年平静，优化器以为分散化还在。Loretan–English 强调，比较「压力期相关」与「全样本相关」时，必须说明压力期如何定义——否则每次都能找到一段相关更高的子样本。预指定压力日（交易所熔断、Lehman 周末、2020 年 3 月）再比较，比在数据里搜最大相关段更干净。</p><p><span class="marginnote">优化器最喜欢的低相关资产，往往是样本里还没一起爆过的品种。把「历史上低相关」当成结构性正交，是在用未发生的危机做隐含担保。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>统计层：共同因子的方差上升时，即使因子载荷不变，\\(\\rho_{ij}= \\beta_i\\beta_j \\sigma_F^2 / (\\sigma_i\\sigma_j)\\) 也会上升。这是 Forbes–Rigobon 的核心，不是传染。额外的传染是载荷本身变了，或出现新的共同因子（融资、流动性）。</p><p>经济层：Brunnermeier 的 loss spiral 与 margin spiral。资产跌价 → 资本与抵押不足 → 卖更多同类可抵押品 → 价格再跌。原本靠不同基本面分散的持仓，在「谁能当抵押、谁被经纪商接受」这一维上变成同一资产。火线抛售的价格冲击是跨名字相关的（Kyle 的 \\(\\lambda\\) 作用在被同时卖的篮子上）。因此相关性崩溃经常与<a href="/quant/liquidity-horizon">变现时间</a>一起出现：你来不及在相关升高之前把篮子拆开。</p><h3 id="与体制、拥挤的交叠" tabindex="-1">与体制、拥挤的交叠 <a class="header-anchor" href="#与体制、拥挤的交叠" aria-label="Permalink to &quot;与体制、拥挤的交叠&quot;">​</a></h3><p>体制切换可以把「高相关」写成一个熊市状态的参数；拥挤把同质策略的持仓重叠写成残差 PCA。相关崩溃是观测现象，机制可能是体制、拥挤、融资或单纯的异方差。处置不同：异方差用标准化；拥挤要降杠杆、避免再纯化；融资要管抵押集中度；真体制切换要改长期配置。只改相关矩阵的乘数，是把所有机制收成一个旋钮，校准一次、下次危机换一种机制时失效。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>多元极值在维度上极难：超过几只资产，尾部建模要靠因子结构或成对估计再拼，正定性与校准都不稳。t copula 只有对称尾，会高估上涨端的共同运动。工程上常用的折中是：日常用 DCC 或收缩协方差，压力用预指定情景把融资相关篮子的相关抬高，并单独用历史压力日做回放，而不是声称估出了「真实的崩溃 copula」。</p><p>不要用指数收益的相关去替代成份股可交易组合的相关：指数有编制与再平衡，危机里的停牌、涨跌停会让你无法复制指数那条路径。也不要把信用 CDS 指数与股票的相关在基差炸开时仍当对冲比不变。</p><p><span class="marginnote">风险平价在 2020 年 3 月的同步去杠杆，是「低波动、中等相关」假设在融资约束下的一次性证伪。事后提高相关假设很容易；事前应限制单一融资渠道上的总风险预算。</span></p>',25)),(e(),s(d,null,{default:r(()=>[c(n,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%85%B1%E5%90%8C%E5%9B%A0%E5%AD%90%E6%B3%A2%E5%8A%A8%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20RHO%5B%22%E8%A7%82%E6%B5%8B%E7%9B%B8%E5%85%B3%E5%8D%87%E9%AB%98%22%5D%0A%20%20T%5B%22%E4%B8%8B%E5%B0%BE%E4%BE%9D%E8%B5%96%20%2F%20%E6%9E%81%E5%80%BC%22%5D%20--%3E%20RHO%0A%20%20L%5B%22%E8%9E%8D%E8%B5%84%E4%B8%8E%E7%81%AB%E7%BA%BF%E6%8A%9B%E5%94%AE%22%5D%20--%3E%20RHO%0A%20%20FR%5B%22Forbes-Rigobon%20%E5%BC%82%E6%96%B9%E5%B7%AE%E5%81%8F%E5%B7%AE%22%5D%20--%3E%20RHO%0A%20%20RHO%20--%3E%20SIG%5B%22%E5%8E%8B%E5%8A%9B%E6%9C%9F%20Sigma%22%5D%0A%20%20SIG%20--%3E%20W%5B%22%E5%B9%B3%E9%9D%99%E6%9C%9F%E6%9C%80%E4%BC%98%E6%9D%83%E9%87%8D%E5%A4%B1%E6%95%88%22%5D%0A%20%20W%20--%3E%20LOSS%5B%22%E5%88%86%E6%95%A3%E5%8C%96%E7%BC%BA%E5%8F%A3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>相关性崩溃是压力期共同运动强于平静期估计，来源包括异方差偏差、真尾部依赖、以及融资/火线抛售造成的同向交易。</li><li>Longin–Solnik、Ang–Chen 记录下行相关更高；Forbes–Rigobon 警告把波动上升读成传染；Brunnermeier 给出流动性螺旋的经济机制。</li><li>先标准化波动，再报告 exceedance correlation；日常 \\(\\Sigma\\) 与压力情景应分开，而不是只用一个滚动 \\(\\rho\\)。</li><li>低相关是优化器的诱饵：未一起爆过的资产，不能当成结构正交。</li><li>出处：Longin and Solnik, <em>Extreme Correlation of International Equity Markets</em>, Journal of Finance, 2001；Ang and Chen, <em>Asymmetric Correlations of Equity Portfolios</em>, Journal of Financial Economics, 2002；Forbes and Rigobon, <em>No Contagion, Only Interdependence</em>, Journal of Finance, 2002；Loretan and English, <em>Evaluating “correlation breakdowns”</em>, Federal Reserve IFDP, 2000；Brunnermeier, <em>Deciphering the Liquidity and Credit Crunch 2007–2008</em>, Journal of Economic Perspectives, 2009。</li></ul>',2))])}const _=i(E,[["render",p]]);export{A as __pageData,_ as default};
